{"content": "from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_header(my_header: str = Header()):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header_accepted_by_default():
    # By default convert_underscores=True, so it should look for 'my-header'
    # But the issue says it currently accepts 'my_header' too.
    response = client.get("/", headers={"my_header": "value"})
    print(f"Response with my_header: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"my_header": "value"}

def test_hyphen_header_accepted_by_default():
    response = client.get("/", headers={"my-header": "value"})
    print(f"Response with my-header: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"my_header": "value"}

def test_underscore_header_accepted_when_convert_underscores_false():
    @app.get("/false")
    async def read_header_false(my_header: str = Header(convert_underscores=False)):
        return {"my_header": my_header}

    response = client.get("/false", headers={"my_header": "value"})
    print(f"Response with my_header (convert_underscores=False): {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"my_header": "value"}

if __name__ == "__main__":
    try:
        test_underscore_header_accepted_by_default()
        print("test_underscore_header_accepted_by_default passed")
    except Exception as e:
        print(f"test_underscore_header_accepted_by_default failed: {e}")

    try:
        test_hyphen_header_accepted_by_default()
        print("test_hyphen_header_accepted_by_default passed")
    except Exception as e:
        print(f"test_hyphen_header_accepted_by_default failed: {e}")

    try:
        test_underscore_header_accepted_when_convert_underscores_false()
        print("test_underscore_header_accepted_when_convert_underscores_false passed")
    except Exception as e:
        print(f"test_underscore_header_accepted_when_convert_underscores_false failed: {e}")
